from __future__ import annotations

import os
from typing import Any

from a2a.server.agent_execution import AgentExecutor, RequestContext
from a2a.server.events import EventQueue
import a2a.helpers as h

from qprompt_langgraph.rag import resource_from_dict, retrieve
from qprompt_langgraph.runtime import (
    call_http,
    evaluate_rules,
    resolve_state_assignments,
    run_container,
    run_query,
    select_candidates,
)
from qprompt_a2a.runtime import build_agent_app, call_llm




class Executor(AgentExecutor):
    async def execute(self, context: RequestContext, event_queue: EventQueue) -> None:
        parts = h.get_data_parts(context.message.parts)
        inputs: dict[str, Any] = parts[0] if parts else {}
        state = dict(inputs)

        result = call_http(
            method='post',
            url='https://api.resend.com/emails',
            inputs={ 'draft_emails': inputs.get('draft_emails') },
            credential='EMAIL_API_KEY',
            tool_config='{"from":"onboarding@resend.dev","to":["yassinouhadi@gmail.com"],"body_map":{"subject":"subject"},"templates":{"html":"<p>{body}</p><p><strong>{job_title}</strong> at {company}</p><p>Apply: {url}</p>"}}',
        )
        state['send_report'] = result

        reply = h.new_data_message(state, context_id=context.context_id, task_id=context.task_id)
        await event_queue.enqueue_event(reply)

    async def cancel(self, context: RequestContext, event_queue: EventQueue) -> None:
        pass


app = build_agent_app(
    name='sendEmails',
    description="Emails yourself one digest message per draft, so you apply manually via each job's real URL. Not cold outreach: scraped listings carry no recruiter address to send to (Jooble's API returns snippets, not full postings), so 'to' is always your own inbox below, not anything the graph extracted.",
    tags=['http'],
    executor=Executor(),
    port=int(os.environ.get("PORT", 8000)),
)

if __name__ == "__main__":
    import uvicorn

    uvicorn.run(app, host="0.0.0.0", port=int(os.environ.get("PORT", 8000)))
